namespace CheckoutPricing.UnitTest;

internal static class Eur
{
    public static int Cents(string amount) =>
        (int)Math.Round(decimal.Parse(amount, CultureInfo.InvariantCulture) * 100m);

    public static string? Code(string code) => code == "none" ? null : code;
