    [InlineData("100.00", LoyaltyTier.Bronze, "9.90")]
    [InlineData("10.00", LoyaltyTier.Gold, "9.90")]
    [InlineData("10.00", LoyaltyTier.Platinum, "0.00")]
    public void S13_ExpressShippingCostsNinePointNinetyFreeForPlatinumOnly(string total, LoyaltyTier tier, string fee) =>
        Assert.Equal(Eur.Cents(fee), Fee(total, tier, express: true));
}

